bsl_m=; if [ -r /usr/lib/breadstick/bsl-os.sh ] && . /usr/lib/breadstick/bsl-os.sh && command -v bsl_pkg_mark >/dev/null 2>&1 && command -v bsl_pkg_also >/dev/null 2>&1 && bsl_pkg_mark repair; then bsl_m=1; fi
( [ -z "$bsl_m" ] || bsl_pkg_also $$
echo '[BSL] checking the package database...'; rpm --verifydb 2>&1; bsl_s=0; { ! command -v bsl_pkg_dupes >/dev/null 2>&1 || bsl_pkg_dupes; } 2>&1 || bsl_s=$?; echo '[BSL] fixing broken dependencies...'; B=; grep -qs '^\[breadstick' /etc/yum.repos.d/*.repo /etc/distro.repos.d/*.repo /usr/share/dnf5/repos.d/*.repo && B='breadstick*.'; V=$(! command -v bsl_pkg_releasever >/dev/null 2>&1 || bsl_pkg_releasever 2>/dev/null); { bsl_t=0; bsl_o=$({ dnf -y ${V:+--releasever=$V} distro-sync --skip-unavailable "--setopt=${B}skip_if_unavailable=True"; } 2>&1) || bsl_t=$?; [ -z "$bsl_o" ] || printf '%s\n' "$bsl_o" | tail -n 3; (exit $bsl_t); } || bsl_s=$?; { ! command -v bsl_pkg_mend >/dev/null 2>&1 || bsl_pkg_mend; } 2>&1 || { [ "$bsl_s" != 0 ] || bsl_s=1; }; dnf clean packages 2>&1; if [ "$bsl_s" = 0 ]; then echo '[BSL] repair finished.'; else echo '[BSL] repair failed.'; (exit $bsl_s); fi
); bsl_rc=$?; [ -z "$bsl_m" ] || bsl_pkg_unmark $bsl_rc; exit $bsl_rc
